  if (need === 'axe') return bestTool('axe') ? key('Click') + ' Chop ' + def.n : '🪓 ' + def.n + ' — you need an Axe';
  if (def.cls === 'crystal' && bestTool('pick') !== 'ironpick') return '💎 ' + def.n + ' — you need an Iron Pickaxe';
